style.css:
@-moz-document domain("tasks.google.com") {
/* GOOGLE TASKS - HACKER GREEN GLASS v1.0.7 | Userstyles.org legacy CSS */

html {
  color-scheme: dark !important;
}

/* Task menus, dialogs, inputs and keyboard focus. */
#TasksApp dialog,
#TasksApp [role="dialog"],
#TasksApp [role="alertdialog"],
#TasksApp [role="menu"],
#TasksApp [role="listbox"] {
  background-color: rgba(2,23,11,.97) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36), 0 14px 38px rgba(0,0,0,.57), 0 0 18px rgba(37,255,110,.14) !important;
}

#TasksApp [role="tooltip"] {
  background-color: rgba(1,20,10,.97) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 0 0 1px rgba(32,243,107,.18) !important;
}

#TasksApp [role="menuitem"]:not([aria-disabled="true"]):hover,
#TasksApp [role="option"]:not([aria-disabled="true"]):hover {
  background-color: rgba(12,91,39,.56) !important;
}

#TasksApp button,
#TasksApp input,
#TasksApp textarea,
#TasksApp select,
#TasksApp [role="menuitem"],
#TasksApp [role="option"],
#TasksApp [role="tooltip"] {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

#TasksApp input,
#TasksApp textarea,
#TasksApp [contenteditable="true"] {
  caret-color: #00ff66 !important;
}

#TasksApp input::placeholder,
#TasksApp textarea::placeholder {
  color: #9ee5b6 !important;
  opacity: 1 !important;
}

#TasksApp input[type="checkbox"] {
  accent-color: #00e85c !important;
}

#TasksApp button:focus-visible,
#TasksApp input:focus-visible,
#TasksApp textarea:focus-visible,
#TasksApp [role="button"]:focus-visible,
#TasksApp [role="menuitem"]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: -2px !important;
}

html body#TasksApp {
  background-color: #0a0a0a !important;
  background-image: linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

/* Let the grid show through the board and the gaps between list cards. */
#TasksApp #yDmH0d,
#TasksApp c-wiz.SSPGKf,
#TasksApp .T4LgNb,
#TasksApp .kFwPee,
#TasksApp .N6pmG,
#TasksApp .cff7Jf,
#TasksApp .ERuXW,
#TasksApp .AZ2Tsb,
#TasksApp .ieAuaf,
#TasksApp .Hm4iQb,
#TasksApp .NbVwSc,
#TasksApp .bRcSk .nuaKyb,
#TasksApp .bRcSk .WGFaob {
  background-color: transparent !important;
  background-image: none !important;
}

/* Calendar-style top bar. Keep the page grid visible through the glass. */
#TasksApp #gb,
#TasksApp [role="banner"] {
  background: rgba(3,33,17,.47) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 -1px rgba(28,240,102,.36) !important;
}

#TasksApp #gb [role="heading"],
#TasksApp #gb a[aria-label="Google Tasks"],
#TasksApp #gb a[aria-label="Tasks"] .gb_2d,
#TasksApp #gb img[src*="tasks"] + span {
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

#TasksApp #gb img[src*="tasks"],
#TasksApp #gb img[alt="Google Tasks"],
#TasksApp #gb img[alt="Tasks"],
#TasksApp #gb a[aria-label="Google Tasks"] svg,
#TasksApp #gb a[aria-label="Tasks"] svg {
  filter: hue-rotate(270deg) saturate(1.3)
    drop-shadow(0 2px 3px rgba(0,255,102,.75))
    drop-shadow(0 2px 8px rgba(0,255,102,.45)) !important;
}

#TasksApp #gb button,
#TasksApp #gb [role="button"],
#TasksApp #gb button[aria-label="Main menu"] svg {
  color: #7fffac !important;
}

#TasksApp #gb button:hover,
#TasksApp #gb [role="button"]:hover {
  background-color: rgba(12,91,39,.56) !important;
}

/* Tasks drawer uses the Calendar drawer's glass, grid and right-edge glow. */
#TasksApp .Pj9zVe {
  background-color: rgba(4,23,15,.96) !important;
  background-image:
    radial-gradient(ellipse 235% 78% at left top, rgba(20,70,40,.46) 0%, rgba(20,70,40,.12) 62%, rgba(20,70,40,0) 100%),
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 100% 100%, 40px 40px, 40px 40px, 100% 4px !important;
  background-position: left top, 0 0, 0 0, 0 0 !important;
  background-repeat: no-repeat, repeat, repeat, repeat !important;
  background-attachment: scroll, fixed, fixed, fixed !important;
  box-shadow: inset -1px 0 0 rgba(0,255,102,.85),
    inset -4px 0 8px -3px rgba(0,255,102,.58),
    inset -10px 0 18px -10px rgba(0,255,102,.35) !important;
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

/* Clear the native drawer fill and the permanent navigation groups. */
#TasksApp .Pj9zVe .UVq0Gb,
#TasksApp .Pj9zVe [role="navigation"] ul[role="menu"],
#TasksApp .Pj9zVe [role="navigation"] ul[role="listbox"] {
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}

#TasksApp .Pj9zVe .RNIJvc,
#TasksApp [role="navigation"] [role="heading"],
#TasksApp [role="navigation"] [aria-expanded]:not([data-is-fab="true"]),
#TasksApp [role="navigation"] [role="option"] {
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

#TasksApp [role="navigation"] [role="option"][aria-selected="true"],
#TasksApp [role="navigation"] [role="tab"][aria-selected="true"],
#TasksApp [role="navigation"] [aria-current="page"],
#TasksApp [role="navigation"] [aria-current="true"],
#TasksApp [role="navigation"] [role="listbox"] [aria-pressed="true"] {
  background: rgba(4,54,27,.83) !important;
  color: #d9ffe6 !important;
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36) !important;
}

#TasksApp [role="navigation"] [role="menuitem"]:not([aria-disabled="true"]):hover,
#TasksApp [role="navigation"] [role="option"]:not([aria-disabled="true"]):hover,
#TasksApp [role="navigation"] [role="tab"]:not([aria-disabled="true"]):hover {
  background-color: rgba(12,91,39,.72) !important;
  color: #d9ffe6 !important;
}

#TasksApp .Pj9zVe [role="menuitem"] .aqdrmf-rymPhb-KkROqb,
#TasksApp [role="navigation"] [role="option"] .google-material-icons,
#TasksApp [role="navigation"] [role="option"] .material-icons-extended,
#TasksApp [role="navigation"] [aria-expanded]:not([data-is-fab="true"]) .google-material-icons {
  color: #7fffac !important;
}

#TasksApp [role="navigation"] button[data-is-fab="true"] {
  border-color: #00e85c !important;
}

#TasksApp .aqdrmf-rymPhb-fpDzbe-fmcmS {
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

#TasksApp .KGC9Kd-muHVFf-bMcfAe + .KGC9Kd-YQoJzd {
  border-color: rgba(28,240,102,.36) !important;
}

#TasksApp .KGC9Kd-muHVFf-bMcfAe:checked + .KGC9Kd-YQoJzd,
#TasksApp .KGC9Kd-muHVFf-bMcfAe[data-indeterminate="true"] + .KGC9Kd-YQoJzd {
  background-color: #00e85c !important;
  border-color: #00e85c !important;
}

#TasksApp .KGC9Kd-YQoJzd .KGC9Kd-SJnn3d {
  color: #001b09 !important;
  border-color: #001b09 !important;
}

/* List cards, task titles, details and completed rows. */
#TasksApp .bRcSk {
  background: rgba(1,22,10,.75) !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36), 0 0 14px rgba(37,255,110,.14) !important;
}

#TasksApp .bRcSk .ZXbQHf {
  background: rgba(3,33,17,.47) !important;
  box-shadow: inset 0 -1px rgba(32,243,107,.18) !important;
}

#TasksApp .bRcSk .kaBGi,
#TasksApp .bRcSk .CLkXBe {
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

#TasksApp .bRcSk .DEh1R,
#TasksApp .bRcSk .oWnhFd .CLkXBe {
  color: #9ee5b6 !important;
}

#TasksApp [data-task-id]:hover,
#TasksApp .bRcSk button[jsname="UsVyAb"]:hover {
  background-color: rgba(12,91,39,.56) !important;
}

#TasksApp [data-task-id]:focus-visible,
#TasksApp [role="option"]:focus-visible {
  outline: 2px solid #00ff66 !important;
  outline-offset: -2px !important;
}

/* Create, Add a task, and list/row controls. */
#TasksApp [role="navigation"] button[data-is-fab="true"],
#TasksApp .bRcSk button[jsname="MhySTb"] {
  background-color: #00e85c !important;
  color: #001b09 !important;
}

#TasksApp [role="navigation"] button[data-is-fab="true"]:not(:disabled):hover,
#TasksApp .bRcSk button[jsname="MhySTb"]:not(:disabled):hover {
  background-color: #38ff87 !important;
  box-shadow: 0 0 14px rgba(37,255,110,.14) !important;
}

#TasksApp .T57Ued-nBWOSb,
#TasksApp .bRcSk button[jsname="MhySTb"] .mUIrbf-vQzf8d {
  color: #001b09 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

#TasksApp button[data-is-fab="true"] .google-material-icons,
#TasksApp button[jsname="MhySTb"] .mUIrbf-kBDsod-Rtc0Jf {
  color: #001b09 !important;
}

#TasksApp .bRcSk button[jsname="UsVyAb"],
#TasksApp .bRcSk [jsname="pzCKEc"],
#TasksApp [data-task-id] button,
#TasksApp [data-task-id] button .material-icons-extended {
  color: #7fffac !important;
}

#TasksApp .bRcSk [jsname="pzCKEc"]:hover,
#TasksApp [data-task-id] button:not(:disabled):hover {
  background-color: rgba(12,91,39,.56) !important;
}

#TasksApp [data-task-id] button[aria-pressed="true"] {
  background-color: rgba(4,54,27,.58) !important;
}

/* Inline task editor. Native menu and tooltip rules are shared with Calendar. */
#TasksApp [data-is-editing="true"],
#TasksApp [data-task-id][data-is-editing="true"]:hover,
#TasksApp input[type="text"],
#TasksApp textarea,
#TasksApp [contenteditable="true"] {
  background-color: rgba(4,43,20,.95) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}

#TasksApp [data-is-editing="true"] {
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36) !important;
}

/* ChatGPT Hacker Green v1.5.3 scrollbar and selection values. */
* {
  scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18);
  scrollbar-width: thin;
}
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background: rgba(0,18,7,.18); }
*::-webkit-scrollbar-thumb {
  background: rgba(29,191,83,.53);
  border-radius: 8px;
}
*::-webkit-scrollbar-thumb:hover { background: #70b68b; }
::selection {
  background: rgba(0,255,102,.35) !important;
  color: #f5fff7 !important;
}
}
